class Solution {
  public int xorAfterQueries(int[] nums, int[][] queries) {
    final long MOD = 1_000_000_007L;
    long[] a = new long[nums.length];
    for (int i = 0; i < a.length; i++) a[i] = nums[i];
    for (int[] q : queries) {
      for (int idx = q[0]; idx <= q[1]; idx += q[2]) a[idx] = a[idx] * q[3] % MOD;
    }
    long xor = 0;
    for (long v : a) xor ^= v;
    return (int) xor;
  }
}
